def digest_bytes(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def digest_file(path: Path, deadline: float | None = None, reserve: float = 20.0) -> str:
    h = hashlib.sha256()
    with path.open('rb') as f:
        for block in iter(lambda: f.read(1024 * 1024), b''):
            if deadline is not None and time.monotonic() >= deadline - reserve:
                raise TimeoutError('deadline reserve reached while hashing pinned inputs')
            h.update(block)
    return h.hexdigest()


def tree_snapshot(root: Path, deadline: float | None = None, reserve: float = 20.0) -> dict:
    """Hash every regular file and record every symlink under the pinned tree."""
    if root.is_symlink() or not root.is_dir():
        raise RuntimeError('node_modules must be a physical directory')
    entries = []
    for current, dirs, files in os.walk(root, topdown=True, followlinks=False):
        if deadline is not None and time.monotonic() >= deadline - reserve:
            raise TimeoutError('deadline reserve reached while snapshotting node_modules')
        base = Path(current)
        kept = []
        for name in sorted(dirs):
            p = base / name
            if p.is_symlink():
                entries.append({'path': p.relative_to(root).as_posix(), 'kind': 'symlink-dir', 'target': os.readlink(p)})
            else:
                kept.append(name)
        dirs[:] = kept
        for name in sorted(files):
            p = base / name
            rel = p.relative_to(root).as_posix()
            if p.is_symlink():
                entries.append({'path': rel, 'kind': 'symlink-file', 'target': os.readlink(p)})
            elif p.is_file():
                entries.append({'path': rel, 'kind': 'file', 'bytes': p.stat().st_size, 'sha256': digest_file(p, deadline, reserve)})
    entries.sort(key=lambda row: row['path'])
    encoded = json.dumps(entries, sort_keys=True, separators=(',', ':')).encode()
    return {'root': str(root.resolve()), 'entryCount': len(entries), 'sha256': digest_bytes(encoded), 'entries': entries}


def source_cohort_digest(inventory: dict, root: Path) -> str:
    """Apply the unmodified generator's sourceCohortSha256 formula to pinned records."""
    sections = []
    for key in ('sourceModules', 'scripts', 'rustModules', 'rustBuildInputs'):
        sections.append('\n'.join(f"{row['path']} {row['sha256']}" for row in inventory[key]))
    sections.append('\n'.join(f"{row['path']} {row['sha256']}" for row in inventory['dependencies']['python']['projects']))
    tail = [digest_file(root / rel) for rel in ('Cargo.lock', 'Cargo.toml', 'package.json', 'bun.lock')]
    return digest_bytes(('\n'.join(sections) + '\n' + '\n'.join(tail)).encode())


class Controller:
    def __init__(self, approvals: dict[str, Path]):
        self.start = time.monotonic()
        self.deadline = self.start + DEADLINE_SECONDS
        self.approvals = approvals
        self.receipt = {
            'status': 'running', 'mode': MODE, 'revision': REV,
            'parentRevision': PARENT, 'deadlineSeconds': DEADLINE_SECONDS,
            'startedUtc': time.strftime('%Y-%m-%dT%H:%M:%SZ', time.gmtime()),
            'controllerPid': os.getpid(), 'controllerPgid': os.getpgid(0),
            'events': [], 'children': [], 'worktree': str(WORK), 'outputDirectory': str(OUT),
        }
        self.child = None
        self.spawn_pending = False
        self.registered = False
        self.output_owned = False
        self.check_started = False
        self.inventory_before = None

    def event(self, name: str, **fields):
        item = {'event': name, 'elapsedSeconds': round(time.monotonic() - self.start, 3), **fields}
        self.receipt['events'].append(item)
        print(json.dumps(item, sort_keys=True), flush=True)

    @staticmethod
    def group_exists(pgid: int) -> bool:
        try:
            os.killpg(pgid, 0)
            return True
        except ProcessLookupError:
            return False

    def bounded_wait_group_absent(self, pgid: int, seconds: float) -> bool:
        until = min(self.deadline - 10, time.monotonic() + seconds)
        while time.monotonic() < until:
            if not self.group_exists(pgid):
                return True
            time.sleep(min(0.1, max(0.0, until-time.monotonic())))
        return not self.group_exists(pgid)

    def run(self, argv: list[str], cwd: Path, timeout: float, cleanup=False) -> tuple[int, str, str]:
        reserve = 15 if cleanup else CLEANUP_RESERVE_SECONDS
        remaining = self.deadline - time.monotonic()
        if remaining <= reserve:
            raise TimeoutError('600-second total deadline reserve reached')
        timeout = min(timeout, remaining - reserve)
        intent = {'argv': argv, 'cwd': str(cwd), 'startedElapsedSeconds': round(time.monotonic()-self.start), 'spawnState': 'in-progress'}
        self.receipt['spawnIntent'] = intent
        self.spawn_pending = True
        try:
            proc = subprocess.Popen(argv, cwd=str(cwd), env=ENV, stdout=subprocess.PIPE,
                                    stderr=subprocess.PIPE, start_new_session=True)
            # Publish the returned handle and deterministic new-session PGID before
            # clearing pessimistic spawn intent. An interrupt in this window remains
            # recoverable as a known owned child, not an unowned successful spawn.
            self.child = proc
            pgid = proc.pid  # start_new_session=True makes the child its session/PGID leader.
            child_record = {'pid': proc.pid, 'pgid': pgid, 'argv': argv,
                            'startedElapsedSeconds': round(time.monotonic()-self.start, 3),
                            'terminalObserved': False, 'groupAbsent': False, 'timedOut': False}
            self.receipt['children'].append(child_record)
            self.receipt['activeChild'] = child_record
            self.spawn_pending = False
            self.receipt.pop('spawnIntent', None)
        except BaseException as exc:
            if self.child is None and self.spawn_pending:
                # Interruption before the returned handle was durably recorded is
                # an unknown spawn. Never infer no child from Popen's missing return.
                self.receipt['spawnOutcomeUnknown'] = True
                self.receipt['spawnIntent'] = {'argv': argv, 'cwd': str(cwd), 'spawnState': 'unknown-after-interruption', 'exceptionType': type(exc).__name__}
                self.event('spawn-outcome-unknown', argv=argv, exceptionType=type(exc).__name__)
            raise
        self.event('child-start', pid=proc.pid, pgid=pgid, argv=argv)
        out = err = b''
        timed_out = False
        group_absent = False
        try:
            try:
                out, err = proc.communicate(timeout=timeout)
            except subprocess.TimeoutExpired as first:
                timed_out = True
                out, err = first.output or b'', first.stderr or b''
                self.event('child-timeout-term', pid=proc.pid, pgid=pgid)
                try: os.killpg(pgid, signal.SIGTERM)
                except ProcessLookupError: pass
                try:
                    out, err = proc.communicate(timeout=min(5, max(0.1, self.deadline-time.monotonic()-25)))
                except subprocess.TimeoutExpired as second:
                    out, err = second.output or out, second.stderr or err
                    self.event('child-timeout-kill', pid=proc.pid, pgid=pgid)
                    try: os.killpg(pgid, signal.SIGKILL)
                    except ProcessLookupError: pass
                    left = self.deadline - time.monotonic() - 20
                    if left <= 0:
                        child_record['terminalUnproven'] = True
                        raise TimeoutError('no time remains for bounded child reap')
                    try:
                        proc.wait(timeout=min(5, left))
                    except subprocess.TimeoutExpired:
                        child_record['terminalUnproven'] = True
                        raise TimeoutError('child process did not reap after SIGKILL within bounded wait')
                    for pipe in (proc.stdout, proc.stderr):
                        if pipe is not None:
                            try: pipe.close()
                            except OSError: pass
            group_absent = self.bounded_wait_group_absent(pgid, 3)
            if not group_absent:
                self.event('child-group-term', pid=proc.pid, pgid=pgid)
                try: os.killpg(pgid, signal.SIGTERM)
                except ProcessLookupError: pass
                group_absent = self.bounded_wait_group_absent(pgid, 4)
            if not group_absent:
                self.event('child-group-kill', pid=proc.pid, pgid=pgid)
                try: os.killpg(pgid, signal.SIGKILL)
                except ProcessLookupError: pass
                group_absent = self.bounded_wait_group_absent(pgid, 5)
        except BaseException as exc:
            # Keep the real process handle and active-child record until cleanup
            # has independently terminated/reaped it and confirmed its PGID absent.
            child_record['interruption'] = {'exceptionType': type(exc).__name__, 'elapsedSeconds': round(time.monotonic()-self.start, 3)}
            child_record['timedOut'] = timed_out
            raise
        if proc.poll() is not None and group_absent:
            child_record.update({'returncode': proc.returncode, 'terminalObserved': True,
                                 'groupAbsent': True, 'timedOut': timed_out,
                                 'endedElapsedSeconds': round(time.monotonic()-self.start, 3)})
            self.receipt.pop('activeChild', None)
            self.child = None
        label = f'child-{proc.pid}'
        out = out or b''; err = err or b''
        (OUT / f'{label}.stdout').write_bytes(out)
        (OUT / f'{label}.stderr').write_bytes(err)
        self.event('child-end', pid=proc.pid, pgid=pgid, returncode=proc.poll(),
                   terminalObserved=proc.poll() is not None, groupAbsent=group_absent,
                   timedOut=timed_out, stdoutBytes=len(out), stdoutSha256=digest_bytes(out),
                   stderrBytes=len(err), stderrSha256=digest_bytes(err))
        if not child_record.get('terminalObserved') or not child_record.get('groupAbsent'):
            raise RuntimeError('child or process group terminal absence not proven; refuse subsequent effects')
        if timed_out:
            raise TimeoutError('child command timed out; a zero exit after timeout is not success')
        if proc.returncode != 0:
            raise RuntimeError(f'command returned {proc.returncode}: {argv}')
        return proc.returncode, out.decode('utf-8', 'replace'), err.decode('utf-8', 'replace')

    def command(self, argv, cwd, timeout, cleanup=False):
        return self.run(argv, cwd, timeout, cleanup)[1]

    def save(self):
        self.receipt['endedUtc'] = time.strftime('%Y-%m-%dT%H:%M:%SZ', time.gmtime())
        self.receipt['elapsedSeconds'] = round(time.monotonic() - self.start, 3)
        if not self.output_owned:
            return
        (OUT / 'receipt.json').write_text(json.dumps(self.receipt, sort_keys=True, indent=2) + '\n')

    def run_check(self):
        controller_sha = digest_file(Path(__file__))
        approval_rows = {}
        for role, path in self.approvals.items():
            if not path.is_file(): raise RuntimeError('approval receipt missing: ' + role)
            gate = json.loads(path.read_text())
            expected_status = 'go' if role == 'coordinator' else 'approved'
            if gate.get('status') != expected_status or gate.get('role') != role or gate.get('revision') != REV or gate.get('mode') != MODE or gate.get('controllerSha256') != controller_sha:
                raise RuntimeError('approval receipt binding mismatch: ' + role)
            approval_rows[role] = {'path': str(path), 'sha256': digest_file(path)}
        self.receipt['controllerSha256'] = controller_sha
        self.receipt['approvalReceipts'] = approval_rows
        if OUT.exists() or WORK.exists():
            raise RuntimeError('refusing pre-existing output or worktree path')
        if digest_file(PREDECESSOR_RECEIPT) != PREDECESSOR_RECEIPT_SHA:
            raise RuntimeError('predecessor receipt hash mismatch')
        if digest_file(PREDECESSOR_CHECK_RECEIPT) != PREDECESSOR_CHECK_RECEIPT_SHA:
            raise RuntimeError('predecessor check receipt hash mismatch')
        if digest_file(BASELINE_INVENTORY) != BASELINE_INVENTORY_SHA:
            raise RuntimeError('predecessor inventory hash mismatch')
        if digest_file(DERIVED_INVENTORY) != DERIVED_INVENTORY_SHA:
            raise RuntimeError('derived candidate inventory hash mismatch')
        if digest_file(DERIVATION_PROOF) != DERIVATION_PROOF_SHA:
            raise RuntimeError('derived candidate proof hash mismatch')
        predecessor = json.loads(PREDECESSOR_RECEIPT.read_text())
        if predecessor.get('status') != 'generation-completed-review-pending' or predecessor.get('mode') != 'generation-only' or predecessor.get('revision') != '091aea5d111045fe70b229bc72fb47ef95febb9d' or predecessor.get('generation', {}).get('returncode') != 0 or predecessor.get('generation', {}).get('timedOut') is not False or predecessor.get('generation', {}).get('inventorySha256') != BASELINE_INVENTORY_SHA or predecessor.get('generation', {}).get('byteIdenticalCopy') is not True or predecessor.get('worktreeCleaned') is not True or predecessor.get('nodeModulesUnchanged') is not True:
            raise RuntimeError('predecessor receipt does not establish the pinned 091 capture')
        predecessor_check = json.loads(PREDECESSOR_CHECK_RECEIPT.read_text())
        predecessor_check_result = predecessor_check.get('check', {})
        if (predecessor_check.get('status') != 'check-completed-review-pending'
                or predecessor_check.get('mode') != 'check-only'
                or predecessor_check.get('revision') != '091aea5d111045fe70b229bc72fb47ef95febb9d'
                or predecessor_check.get('parentRevision') != '937dcd04b365dafe8ebec4565aff392fa67126d8'
                or predecessor_check_result.get('argv') != [PYTHON, 'scripts/rust-inventory.py', '--check']
                or predecessor_check_result.get('returncode') != 0
                or predecessor_check_result.get('timedOut') is not False
                or predecessor_check_result.get('unchanged') is not True
                or predecessor_check_result.get('inventorySha256Before') != BASELINE_INVENTORY_SHA
                or predecessor_check_result.get('inventorySha256After') != BASELINE_INVENTORY_SHA
                or predecessor_check.get('inventoryAfterCheckSha256') != BASELINE_INVENTORY_SHA
                or predecessor_check.get('inventoryAfterCleanupCheck', {}).get('sha256') != BASELINE_INVENTORY_SHA
                or predecessor_check.get('inventoryAfterCleanupCheck', {}).get('unchangedFromPinnedGeneration') is not True
                or predecessor_check.get('worktreeCleaned') is not True
                or predecessor_check.get('nodeModulesUnchanged') is not True):
            raise RuntimeError('prior check receipt does not prove successful 091 check and cleanup against the pinned inventory')
        derivation = json.loads(DERIVATION_PROOF.read_text())
        if derivation.get('status') != 'derived-candidate-only-not-generated-or-current' or derivation.get('commit') != REV or derivation.get('parent') != PARENT or derivation.get('target') != 'python/tests/test_python_artifact_version.py' or derivation.get('baselineInventorySha256') != BASELINE_INVENTORY_SHA or derivation.get('derivedInventorySha256') != DERIVED_INVENTORY_SHA or derivation.get('baselineTestSha256') != BASELINE_SCRIPT_SHA or derivation.get('candidateTestSha256') != CANDIDATE_SCRIPT_SHA or derivation.get('changedJsonPaths') != ['$.capture.sourceCohortSha256', '$.scripts[51].bytes', '$.scripts[51].sha256'] or derivation.get('otherJsonValuesUnchanged') is not True:
            raise RuntimeError('derived inventory proof does not match this exact source transition')
        OUT.mkdir(parents=True)
        self.output_owned = True
        if self.command([GIT, 'rev-parse', REV], ROOT, 10).strip() != REV:
            raise RuntimeError('target commit unavailable or not exact')
        parent = self.command([GIT, 'rev-parse', f'{REV}^'], ROOT, 10).strip()
        if parent != PARENT:
            raise RuntimeError('target parent mismatch')
        changed = self.command([GIT, 'diff', '--name-only', f'{PARENT}..{REV}'], ROOT, 10).splitlines()
        if changed != EXPECTED_DIFF:
            raise RuntimeError(f'unexpected source diff: {changed!r}')
        nm = ROOT / 'node_modules'
        snapshot = tree_snapshot(nm, self.deadline, CLEANUP_RESERVE_SECONDS)
        snapshot_path = OUT / 'node-modules-before.json'
        snapshot_path.write_text(json.dumps(snapshot['entries'], sort_keys=True, separators=(',', ':')) + '\n')
        self.receipt['nodeModulesBefore'] = {'root': snapshot['root'], 'entryCount': snapshot['entryCount'], 'sha256': snapshot['sha256'], 'inventoryPath': str(snapshot_path), 'inventoryFileSha256': digest_file(snapshot_path)}
        self.receipt['tools'] = {}
        for name, exe in (('python', PYTHON), ('bun', BUN), ('git', GIT)):
            expected_version, expected_sha = PINNED_TOOLS[exe]
            if not Path(exe).is_file(): raise RuntimeError(f'missing pinned {name}')
            version_args = ['--version']
            version = self.command([exe, *version_args], ROOT, 10).strip()
            actual_sha = digest_file(Path(exe))
            if version != expected_version or actual_sha != expected_sha:
                raise RuntimeError(f'{name} version/binary pin mismatch')
            self.receipt['tools'][name] = {'path': exe, 'version': version, 'sha256': actual_sha}
        self.receipt['bunLockSha256'] = digest_file(ROOT / 'bun.lock')
        if self.receipt['bunLockSha256'] != LOCK_SHA:
            raise RuntimeError('shared Bun lock differs from reviewed pin')
        # Pessimistically own the path before dispatch: interrupted git worktree
        # registration must still enter cleanup/reconciliation.
        self.registered = True
        self.command([GIT, 'worktree', 'add', '--detach', str(WORK), REV], ROOT, 45)
        self.receipt['worktreeHead'] = self.command([GIT, 'rev-parse', 'HEAD'], WORK, 5).strip()
        if self.receipt['worktreeHead'] != REV: raise RuntimeError('worktree HEAD mismatch')
        for rel, expected in {'scripts/rust-inventory.py': '2ddc70900350dfdd613196e3e8a319150a2b5421fe4f2c0b41da6365777e8f85', 'scripts/rust-inventory-typescript.ts': 'e9cd4ec974b629d262bc73ca73b39cd479732fd14674e72b0810c571d56acccd', 'bun.lock': LOCK_SHA}.items():
            actual = digest_file(WORK / rel)
            if actual != expected: raise RuntimeError('frozen generator input hash mismatch: ' + rel)
        (WORK / 'node_modules').symlink_to(nm.resolve(), target_is_directory=True)
        if (WORK / 'node_modules').resolve() != nm.resolve(): raise RuntimeError('node_modules link mismatch')
        inventory = WORK / INVENTORY_REL
        if not inventory.parent.is_dir(): raise RuntimeError('generator output parent absent')
        checkout_inventory_sha = digest_file(inventory) if inventory.exists() else None
        self.receipt['inventoryCheckoutBeforeSeed'] = {'exists': inventory.exists(), 'sha256': checkout_inventory_sha}
        if checkout_inventory_sha != INVENTORY_CHECKOUT_BASELINE_SHA:
            raise RuntimeError('committed checkout inventory baseline changed')
        if checkout_inventory_sha != BASELINE_INVENTORY_SHA:
            raise RuntimeError('b4 committed inventory is not the pinned 091 predecessor capture')
        # Validate the derived file's only record-level changes before using it
        # as the seed for --check. This is still a derived candidate, not a
        # generator result or currentness claim.
        baseline_json = json.loads(BASELINE_INVENTORY.read_text())
        derived_json = json.loads(DERIVED_INVENTORY.read_text())
        target = 'python/tests/test_python_artifact_version.py'
        source_bytes = self.command([GIT, 'show', f'{REV}:{target}'], ROOT, 10).encode()
        if digest_bytes(source_bytes) != CANDIDATE_SCRIPT_SHA:
            raise RuntimeError('candidate source bytes do not match the exact revision')
        target_record = next(row for row in derived_json['scripts'] if row['path'] == target)
        if target_record['sha256'] != CANDIDATE_SCRIPT_SHA or target_record['bytes'] != len(source_bytes):
            raise RuntimeError('derived script record does not match candidate source bytes')
        if baseline_json['counts'] != derived_json['counts'] or baseline_json['activation'] != derived_json['activation']:
            raise RuntimeError('derived candidate changed activation or inventory counts')
        if source_cohort_digest(baseline_json, WORK) != baseline_json['capture']['sourceCohortSha256']:
            raise RuntimeError('pinned predecessor source cohort digest is inconsistent')
        if source_cohort_digest(derived_json, WORK) != derived_json['capture']['sourceCohortSha256']:
            raise RuntimeError('derived candidate source cohort digest is inconsistent')
        inventory_diff = []
        def collect_diff(left, right, path='$'):
            if type(left) is not type(right):
                inventory_diff.append(path); return
            if isinstance(left, dict):
                if left.keys() != right.keys():
                    inventory_diff.append(path); return
                for key in left: collect_diff(left[key], right[key], f'{path}.{key}')
            elif isinstance(left, list):
                if len(left) != len(right):
                    inventory_diff.append(path); return
                for index, (a, b) in enumerate(zip(left, right)):
                    collect_diff(a, b, f'{path}[{index}]')
            elif left != right:
                inventory_diff.append(path)
        collect_diff(baseline_json, derived_json)
        allowed_diff = ['$.capture.sourceCohortSha256', '$.scripts[51].bytes', '$.scripts[51].sha256']
        if sorted(inventory_diff) != allowed_diff:
            raise RuntimeError(f'derived candidate inventory has unexpected changes: {inventory_diff!r}')
        shutil.copyfile(DERIVED_INVENTORY, inventory)
        staged_sha = digest_file(inventory)
        if staged_sha != DERIVED_INVENTORY_SHA:
            raise RuntimeError('staged candidate inventory differs from pinned derived input')
        retained = OUT / 'inventory.derived-candidate.json'
        shutil.copyfile(inventory, retained)
        self.receipt['derivedCandidateInput'] = {'status': 'derived-not-generated-or-current', 'predecessorGenerationReceiptPath': str(PREDECESSOR_RECEIPT), 'predecessorGenerationReceiptSha256': PREDECESSOR_RECEIPT_SHA, 'predecessorCheckReceiptPath': str(PREDECESSOR_CHECK_RECEIPT), 'predecessorCheckReceiptSha256': PREDECESSOR_CHECK_RECEIPT_SHA, 'predecessorInventoryPath': str(BASELINE_INVENTORY), 'predecessorInventorySha256': BASELINE_INVENTORY_SHA, 'derivationProofPath': str(DERIVATION_PROOF), 'derivationProofSha256': DERIVATION_PROOF_SHA, 'inventoryPath': str(DERIVED_INVENTORY), 'inventorySha256': DERIVED_INVENTORY_SHA, 'stagedPath': str(retained), 'stagedSha256': digest_file(retained)}
        self.check_started = True
        # The only product-source execution is the unmodified checker against the pinned derived candidate.
        out = self.command([PYTHON, 'scripts/rust-inventory.py', '--check'], WORK, CHECK_LIMIT_SECONDS)
        after_sha = digest_file(inventory)
        self.receipt['inventoryAfterCheckSha256'] = after_sha
        self.receipt['check'] = {'argv': [PYTHON, 'scripts/rust-inventory.py', '--check'], 'returncode': 0, 'timedOut': False, 'stdout': out[-12000:], 'inventorySha256Before': staged_sha, 'inventorySha256After': after_sha, 'unchanged': after_sha == staged_sha}
        if after_sha != DERIVED_INVENTORY_SHA:
            raise RuntimeError('check changed the staged inventory bytes')
        self.receipt['status'] = 'check-completed-review-pending'

    def cleanup(self):
        unresolved = self.receipt.get('spawnOutcomeUnknown', False)
        if self.spawn_pending and self.child is None:
            unresolved = True
            self.receipt['unknownSpawnPreserved'] = True
        if self.child is not None:
            proc = self.child
            # Retain the owned process object throughout bounded termination.
            pgid = self.receipt.get('activeChild', {}).get('pgid', proc.pid)
            if not self.receipt.get('activeChild'):
                row = {'pid': proc.pid, 'pgid': pgid, 'argv': self.receipt.get('spawnIntent', {}).get('argv', []), 'terminalObserved': False, 'groupAbsent': False, 'recoveredDuringCleanup': True}
                self.receipt['children'].append(row)
                self.receipt['activeChild'] = row
            if pgid is None:
                self.receipt['cleanupChildTerminalUnproven'] = True
                unresolved = True
            else:
                try: os.killpg(pgid, signal.SIGTERM)
                except ProcessLookupError: pass
                try: proc.wait(timeout=min(4, max(0.1, self.deadline-time.monotonic()-20)))
                except subprocess.TimeoutExpired:
                    try: os.killpg(pgid, signal.SIGKILL)
                    except ProcessLookupError: pass
                    try: proc.wait(timeout=min(4, max(0.1, self.deadline-time.monotonic()-15)))
                    except subprocess.TimeoutExpired:
                        self.receipt['cleanupChildTerminalUnproven'] = True
                group_absent = self.bounded_wait_group_absent(pgid, 4)
                if not group_absent:
                    try: os.killpg(pgid, signal.SIGKILL)
                    except ProcessLookupError: pass
                    group_absent = self.bounded_wait_group_absent(pgid, 4)
                terminal = proc.poll() is not None
                row = self.receipt.get('activeChild')
                if isinstance(row, dict):
                    row.update({'returncode': proc.poll(), 'terminalObserved': terminal,
                                'groupAbsent': group_absent, 'cleanupAttempted': True,
                                'endedElapsedSeconds': round(time.monotonic()-self.start, 3)})
                self.receipt['cleanupChildState'] = {'pid': proc.pid, 'pgid': pgid, 'returncode': proc.poll(), 'terminalObserved': terminal, 'groupAbsent': group_absent}
                if terminal and group_absent:
                    for pipe in (proc.stdout, proc.stderr):
                        if pipe is not None:
                            try: pipe.close()
                            except OSError: pass
                    self.receipt.pop('activeChild', None)
                    self.child = None
                    self.spawn_pending = False
                    self.receipt.pop('spawnIntent', None)
                else:
                    unresolved = True
        can_remove = self.registered and not unresolved and not self.spawn_pending and self.child is None and not self.receipt.get('activeChild') and all(c.get('terminalObserved') and c.get('groupAbsent') for c in self.receipt['children'])
        if self.registered and can_remove:
            inventory = WORK / INVENTORY_REL
            if self.output_owned and self.check_started and inventory.is_file():
                actual = digest_file(inventory)
                self.receipt['inventoryAfterCleanupCheck'] = {'sha256': actual, 'unchangedFromDerivedCandidate': actual == DERIVED_INVENTORY_SHA}
                if actual != DERIVED_INVENTORY_SHA:
                    changed = OUT / 'inventory.after-check.json'
                    shutil.copyfile(inventory, changed)
                    self.receipt['unexpectedChangedInventory'] = {'path': str(changed), 'sha256': digest_file(changed)}
            try:
                self.command([GIT, 'worktree', 'remove', '--force', str(WORK)], ROOT, 25, cleanup=True)
                self.receipt['worktreeCleaned'] = not WORK.exists()
            except BaseException as exc:
                self.receipt['cleanupFailure'] = repr(exc)
                self.receipt['worktreeCleaned'] = False
        elif self.registered:
            self.receipt['worktreeCleaned'] = False
            self.receipt['cleanupRefusedLiveOrUnprovenChild'] = True
        else:
            self.receipt['worktreeCleaned'] = not WORK.exists()
        try:
            if not self.output_owned:
                raise RuntimeError('attempt does not own output directory; skipping node_modules post-snapshot')
            if time.monotonic() >= self.deadline - 8:
                raise TimeoutError('insufficient deadline to verify node_modules cleanup snapshot')
            final = tree_snapshot(ROOT / 'node_modules', self.deadline, 5.0)
            after_path = OUT / 'node-modules-after.json'
            after_path.write_text(json.dumps(final['entries'], sort_keys=True, separators=(',', ':')) + '\n')
            self.receipt['nodeModulesAfter'] = {'root': final['root'], 'entryCount': final['entryCount'], 'sha256': final['sha256'], 'inventoryPath': str(after_path), 'inventoryFileSha256': digest_file(after_path)}
            self.receipt['nodeModulesUnchanged'] = final['sha256'] == self.receipt.get('nodeModulesBefore', {}).get('sha256') and final['entryCount'] == self.receipt.get('nodeModulesBefore', {}).get('entryCount')
        except BaseException as exc:
            self.receipt['nodeModulesAfterError'] = repr(exc)
            self.receipt['nodeModulesUnchanged'] = False
        if not self.receipt.get('worktreeCleaned') or not self.receipt.get('nodeModulesUnchanged'):
            self.receipt['status'] = 'failed-or-cleanup-unproven'


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--execute', action='store_true', help='requires approvals; otherwise print plan only')
    parser.add_argument('--root-review', type=Path)
    parser.add_argument('--sol-review', type=Path)
    parser.add_argument('--resource-go', type=Path)
    args = parser.parse_args()
    if not args.execute:
        print(json.dumps({'status': 'prepared-not-launched', 'mode': MODE, 'revision': REV, 'parentRevision': PARENT,
                          'output': str(OUT), 'deadlineSeconds': DEADLINE_SECONDS,
                          'checkOnly': True, 'derivedCandidateOnly': True, 'predecessorReceiptSha256': PREDECESSOR_RECEIPT_SHA,
                          'predecessorCheckReceiptSha256': PREDECESSOR_CHECK_RECEIPT_SHA,
                          'predecessorInventorySha256': BASELINE_INVENTORY_SHA, 'derivedInventorySha256': DERIVED_INVENTORY_SHA,
                          'approvalRequired': True}, sort_keys=True))
        return 0
    if any(x is None for x in (args.root_review, args.sol_review, args.resource_go)):
        parser.error('--execute requires --root-review, --sol-review, and --resource-go')
    ctl = Controller({'root': args.root_review, 'sol': args.sol_review, 'coordinator': args.resource_go})
    try:
        ctl.run_check()
    except BaseException as exc:
        ctl.receipt['status'] = 'failed'
        ctl.receipt['failure'] = repr(exc)
        ctl.receipt['traceback'] = traceback.format_exc()
    finally:
        ctl.cleanup()
        if OUT.exists(): ctl.save()
    return 0 if ctl.receipt.get('status') == 'check-completed-review-pending' and ctl.receipt.get('worktreeCleaned') and ctl.receipt.get('nodeModulesUnchanged') else 1

if __name__ == '__main__':
    raise SystemExit(main())
